import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Functions","description":"","frontmatter":{"title":"Functions"},"headers":[],"relativePath":"language-reference/functions.md","filePath":"language-reference/functions.md"}'),c={name:"language-reference/functions.md"};function s(d,e,i,r,f,u){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h1><p>Fault has three kinds of functions: <code>func</code>, <code>sfunc</code>, and <code>unfunc</code>. Because Fault is a specification language and not a programming language, functions aren&#39;t about executing instruction but rather defining how the logic might branch out to different scenarios if that function were executed.</p><table tabindex="0"><thead><tr><th>Keyword</th><th>Where it lives</th><th>What it expresses</th></tr></thead><tbody><tr><td><code>func</code></td><td><code>flow{}</code> in <code>.fspec</code> files</td><td>A stock value is changed somehow</td></tr><tr><td><code>sfunc</code></td><td><code>component</code> states in <code>.fsystem</code> files</td><td>The state machine transitions</td></tr><tr><td><code>unfunc</code></td><td><code>flow{}</code> in <code>.fspec</code> files</td><td>The preconditions and effects of a black box function</td></tr></tbody></table><h2 id="func" tabindex="-1"><code>func</code> <a class="header-anchor" href="#func" aria-label="Permalink to &quot;`func`&quot;">​</a></h2><p>The standard function. Used inside <code>flow{}</code> definitions to describe how a flow changes stocks. See <a href="./flows.html">Flows</a> for syntax and examples.</p><h2 id="sfunc" tabindex="-1"><code>sfunc</code> <a class="header-anchor" href="#sfunc" aria-label="Permalink to &quot;`sfunc`&quot;">​</a></h2><p>State functions live inside <code>component</code> definitions and describe what happens when a component is in a particular state. The body may contain <code>advance()</code>, <code>stay()</code>, <code>leave()</code>, flow triggers, and stock conditionals. It may <strong>not</strong> directly mutate stocks — that is the job of flows. See <a href="./states.html">States</a> for syntax and examples.</p><h2 id="unfunc" tabindex="-1"><code>unfunc</code> <a class="header-anchor" href="#unfunc" aria-label="Permalink to &quot;`unfunc`&quot;">​</a></h2><p>Short for &quot;unimplemented function.&quot; A declarative alternative to <code>func</code> that uses <code>requires</code> and <code>emits</code> clauses instead of imperative steps. The solver uses these clauses to determine when a function can be selected and what it does when it is. <code>unfunc</code> is the primary building block for <a href="./../model-types/program-synthesis.html">program synthesis</a>. See <a href="./flows.html#declarative-functions-unfunc">Flows</a> for syntax and examples.</p>',9)])])}const m=t(c,[["render",s]]);export{h as __pageData,m as default};
